window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-849281ca0993a1ee"]={"versions": [{"id": "FIG-849281ca0993a1ee", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Datenfluss- und Architekturdiagramm zur Veranschaulichung des Logging-Prozesses im Non-Verbose-Modus gemäß AUTOSAR PRS LogAndTraceProtocol. Es zeigt den transport- und plattformübergreifenden Weg von Log-Nachrichten aus ECU-Anwendungen über das zentrale Dlt-Modul bis hin zu einem externen Logging-/Tracing-Tool. Das Diagramm deckt sowohl die Classic Platform (<code>DLT</code>) als auch die Adaptive Platform (<code>ara::log</code>) ab.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ECU (Electronic Control Unit)</strong>: Begrenzender Systemkontext für die loggenden Applikationen und die Laufzeitumgebung.</li>\n<li><strong>Application</strong>: Drei exemplarische Anwendungsblöcke (<code>Application</code>) auf der ECU als Quellen für Log-Ereignisse.</li>\n<li><strong>Dlt module</strong>: Zentrales Protokoll- und Verarbeitungsmodul auf der ECU, ausgewiesen als Classic-DLT (<code>DLT</code>) oder Adaptive-Logging-Instanz (<code>ara::log</code>).</li>\n<li><strong>Meta-Informationsdatei</strong> (Dokumentensymbol): Externe Beschreibungsdatei (z. B. XML/FIBEX/ARXML) mit Metadaten zur Decodierung und Zuordnung der kompakten Non-Verbose-IDs.</li>\n<li><strong>Externes Test-/Diagnosegerät</strong> (Laptop-Symbol): Empfänger, Anzeigegerät und Speicherort für DLT-Nachrichten und Auswertungsstation unter Nutzung der Metainformationen.</li>\n<li><strong>Schnittstellen</strong>:</li>\n<li>Interne Schnittstelle / Datenpfad zwischen <code>Application</code> und <code>Dlt module</code> zur Übergabe von Log-Rohdaten.</li>\n<li>Externe Diagnoseschnittstelle / Kommunikationskanal (z. B. Ethernet, CAN, FlexRay, USB) vom <code>Dlt module</code> zum externen Tool.</li>\n<li>Dateischnittstelle / Importpfad für Meta-Informationen in das externe Tool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Nummerierter Ablauf in fünf Schritten:</p>\n<ol class=\"fig-list\">\n<li><strong>provide log data</strong>: Eine <code>Application</code> übergibt Log-Daten (einschließlich Message-IDs und Parameterwerte) an das <code>Dlt module</code>.</li>\n<li><strong>filter/generate Dlt message</strong>: Das <code>Dlt module</code> filtert die Daten nach konfigurierten Log-Leveln und packt sie in das binäre DLT-Nachrichtenformat des Non-Verbose-Modus (Übertragung von IDs statt Volltext-Strings).</li>\n<li><strong>send Dlt message</strong>: Das <code>Dlt module</code> sendet die generierten DLT-Nachrichten über die ECU-Kommunikationsschnittstelle an das Logging-Tool.</li>\n<li><strong>provide meta information</strong>: Die Metainformationsdatei wird dem externen Tool bereitgestellt/eingelesen, um die Zuordnung von IDs zu Klartexten, Argumenttypen und Kontexten zu ermöglichen.</li>\n<li><strong>store Dlt message</strong>: Das externe Tool empfängt die DLT-Nachrichten und speichert bzw. verarbeitet sie.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Im Non-Verbose-Modus werden zur Reduktion von Buslast und ECU-Laufzeitaufwand keine Klartextbeschreibungen oder vollständigen Format-Strings im DLT-Payload übertragen, sondern kompakte numerische Identifikatoren (Message IDs / Static IDs). Entwickler müssen sicherstellen, dass die zugehörigen Metadaten synchron zum jeweiligen Softwarestand vorliegen, da das externe Tool die binär empfangenen und gespeicherten Non-Verbose-Nachrichten andernfalls nicht decodieren oder semantisch auflösen kann. Die Implementierung muss sowohl für AUTOSAR Classic als auch für AUTOSAR Adaptive die einheitliche Payload-Strukturierung gemäß Protokollspezifikation einhalten.</p>"}, {"id": "FIG-e6372382420c968a", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Datenfluss- und Architekturdiagramm zur Veranschaulichung des Logging-Prozesses im Non-Verbose-Modus gemäß AUTOSAR PRS LogAndTraceProtocol. Es zeigt den transport- und plattformübergreifenden Weg von Log-Nachrichten aus ECU-Anwendungen über das zentrale Dlt-Modul bis hin zu einem externen Logging-/Tracing-Tool. Das Diagramm deckt sowohl die Classic Platform (<code>DLT</code>) als auch die Adaptive Platform (<code>ara::log</code>) ab.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ECU (Electronic Control Unit)</strong>: Begrenzender Systemkontext für die loggenden Applikationen und die Laufzeitumgebung.</li>\n<li><strong>Application</strong>: Drei exemplarische Anwendungsblöcke (<code>Application</code>) auf der ECU als Quellen für Log-Ereignisse.</li>\n<li><strong>Dlt module</strong>: Zentrales Protokoll- und Verarbeitungsmodul auf der ECU, ausgewiesen als Classic-DLT (<code>DLT</code>) oder Adaptive-Logging-Instanz (<code>ara::log</code>).</li>\n<li><strong>Meta-Informationsdatei</strong> (Dokumentensymbol): Externe Beschreibungsdatei (z. B. XML/FIBEX/ARXML) mit Metadaten zur Decodierung und Zuordnung der kompakten Non-Verbose-IDs.</li>\n<li><strong>Externes Test-/Diagnosegerät</strong> (Laptop-Symbol): Empfänger, Anzeigegerät und Speicherort für DLT-Nachrichten und Auswertungsstation unter Nutzung der Metainformationen.</li>\n<li><strong>Schnittstellen</strong>:</li>\n<li>Interne Schnittstelle / Datenpfad zwischen <code>Application</code> und <code>Dlt module</code> zur Übergabe von Log-Rohdaten.</li>\n<li>Externe Diagnoseschnittstelle / Kommunikationskanal (z. B. Ethernet, CAN, FlexRay, USB) vom <code>Dlt module</code> zum externen Tool.</li>\n<li>Dateischnittstelle / Importpfad für Meta-Informationen in das externe Tool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Nummerierter Ablauf in fünf Schritten:</p>\n<ol class=\"fig-list\">\n<li><strong>provide log data</strong>: Eine <code>Application</code> übergibt Log-Daten (einschließlich Message-IDs und Parameterwerte) an das <code>Dlt module</code>.</li>\n<li><strong>filter/generate Dlt message</strong>: Das <code>Dlt module</code> filtert die Daten nach konfigurierten Log-Leveln und packt sie in das binäre DLT-Nachrichtenformat des Non-Verbose-Modus (Übertragung von IDs statt Volltext-Strings).</li>\n<li><strong>send Dlt message</strong>: Das <code>Dlt module</code> sendet die generierten DLT-Nachrichten über die ECU-Kommunikationsschnittstelle an das Logging-Tool.</li>\n<li><strong>provide meta information</strong>: Die Metainformationsdatei wird dem externen Tool bereitgestellt/eingelesen, um die Zuordnung von IDs zu Klartexten, Argumenttypen und Kontexten zu ermöglichen.</li>\n<li><strong>store Dlt message</strong>: Das externe Tool empfängt die DLT-Nachrichten und speichert bzw. verarbeitet sie.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Im Non-Verbose-Modus werden zur Reduktion von Buslast und ECU-Laufzeitaufwand keine Klartextbeschreibungen oder vollständigen Format-Strings im DLT-Payload übertragen, sondern kompakte numerische Identifikatoren (Message IDs / Static IDs). Entwickler müssen sicherstellen, dass die zugehörigen Metadaten synchron zum jeweiligen Softwarestand vorliegen, da das externe Tool die binär empfangenen und gespeicherten Non-Verbose-Nachrichten andernfalls nicht decodieren oder semantisch auflösen kann. Die Implementierung muss sowohl für AUTOSAR Classic als auch für AUTOSAR Adaptive die einheitliche Payload-Strukturierung gemäß Protokollspezifikation einhalten.</p>"}], "trans": [{"from": "FIG-849281ca0993a1ee", "to": "FIG-e6372382420c968a", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
